END_STRUCT
END_TYPE

TYPE stMeasure :
STRUCT
	{attribute 'OPC.UA.DA' := '1'}
	ActualValue : LREAL;
	{attribute 'OPC.UA.DA' := '1'}
	Unit : STRING;
	{attribute 'OPC.UA.DA' := '1'}
	SerialNumber : STRING;
END_STRUCT
END_TYPE

TYPE stRingBuffer :
STRUCT
	{attribute 'OPC.UA.DA' := '1'}
	Buffer : ARRAY[1..4096] OF BYTE;
	{attribute 'OPC.UA.DA' := '1'}
	RdIdx : UINT;
	{attribute 'OPC.UA.DA' := '1'}
	WrIdx : UINT;
	{attribute 'OPC.UA.DA' := '1'}
	BufferSize : UINT := 4096;
END_STRUCT
END_TYPE

TYPE stSerialConfiguration :
STRUCT
	{attribute 'OPC.UA.DA' := '1'}
	BaudRate : UDINT := 57600;
	{attribute 'OPC.UA.DA' := '1'}
	Parity : INT := 0;
	{attribute 'OPC.UA.DA' := '1'}
	DataBits : INT := 8;
	{attribute 'OPC.UA.DA' := '1'}
	StopBits : INT := 1;
	{attribute 'OPC.UA.DA' := '1'}
	DTR : BOOL := FALSE;
	{attribute 'OPC.UA.DA' := '1'}
	RTS : BOOL := FALSE;
END_STRUCT
END_TYPE

TYPE stSerialConnection :
STRUCT
	{attribute 'OPC.UA.DA' := '1'}
	TxBuffer : stRingBuffer;
	{attribute 'OPC.UA.DA' := '1'}
	RxBuffer : stRingBuffer;
	{attribute 'OPC.UA.DA' := '1'}
