	{attribute 'OPC.UA.DA' := '1'}
	RxError : ComError_t;
END_STRUCT
END_TYPE

TYPE stSerialInternal :
STRUCT
	{attribute 'OPC.UA.DA' := '1'}
	RxBuffer : ComBuffer;
	{attribute 'OPC.UA.DA' := '1'}
